/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png').convert('RGB'))
r,g,b=np.moveaxis(im,-1,0)
roi=np.zeros(r.shape,bool);roi[80:205,300:480]=1
conds={
'bright':roi&(r>75)&(r>g*1.05)&(g>b*1.05),
'wood':roi&(r>55)&(r>g*1.12)&(g>b*1.15),
'notgray':roi&(r>70)&((r.astype(int)-b)>20),
}
for name,m in conds.items():
 n,l,s,c=cv2.connectedComponentsWithStats(m.astype('uint8'),8)
 print('\\n',name,m.sum())
 for i in sorted(range(1,n), key=lambda z:s[z,4],reverse=True)[:20]:
  x,y,w,h,a=s[i]
  if a>5: print(x,y,w,h,a,np.round(c[i],1))
# local runs of candidate at each y
m=conds['notgray']
for y in range(85,205,3):
 xs=np.flatnonzero(m[y]); runs=[]
 if len(xs):
  bd=np.r_[0,np.where(np.diff(xs)>1)[0]+1,len(xs)]
  for a,z in zip(bd[:-1],bd[1:]):
   if xs[z-1]-xs[a]+1>=2:runs.append((xs[a],xs[z-1]))
 print(y,runs)
PY"
